def seed_expanded(keep_lines=False):
    conn   = get_conn()
    cursor = conn.cursor()

    # Clear game data — always preserve players so IDs stay stable
    cursor.execute("DELETE FROM backtest_results")
    cursor.execute("DELETE FROM game_logs")
    if not keep_lines:
        cursor.execute("DELETE FROM prop_lines")
        cursor.execute("DELETE FROM players")
    conn.commit()
    msg = ("Cleared game logs — players and prop lines preserved"
           if keep_lines else "Cleared all tables for fresh seed")
    print(msg)

    total_players = 0
    total_logs    = 0

    for player_name, data in PLAYERS_2025.items():
        pos  = data['pos']
        team = data['team']

        # INSERT OR IGNORE keeps existing player IDs stable
        cursor.execute(
            "INSERT OR IGNORE INTO players (name, team, position) VALUES (?,?,?)",
            (player_name, team, pos)
        )
        cursor.execute("SELECT id FROM players WHERE name=?", (player_name,))
        row = cursor.fetchone()
        if not row:
            continue
        pid = row[0]

        for log in data['logs']:
            week      = log[0]
            opp       = log[1]
            home_away = log[2]
            result    = log[3]

            if pos == 'QB':
                pass_yds,pass_att,pass_tds,rush_yds = log[4],log[5],log[6],log[7]
                cursor.execute("""
                    INSERT INTO game_logs
                    (player_id,season,week,team,opponent,home_away,result,
                     pass_yds,pass_att,pass_tds,rush_yds)
                    VALUES (?,2025,?,?,?,?,?,?,?,?,?)
                """, (pid,week,team,opp,home_away,result,
                      pass_yds,pass_att,pass_tds,rush_yds))
            elif pos == 'RB':
                rush_yds,rush_att,recs,rec_yds = log[4],log[5],log[6],log[7]
                cursor.execute("""
                    INSERT INTO game_logs
                    (player_id,season,week,team,opponent,home_away,result,
                     rush_yds,rush_att,receptions,rec_yds)
                    VALUES (?,2025,?,?,?,?,?,?,?,?,?)
                """, (pid,week,team,opp,home_away,result,
                      rush_yds,rush_att,recs,rec_yds))
            else:  # WR, TE
                rec_yds,recs,targets = log[4],log[5],log[6]
                cursor.execute("""
                    INSERT INTO game_logs
                    (player_id,season,week,team,opponent,home_away,result,
                     targets,receptions,rec_yds)
                    VALUES (?,2025,?,?,?,?,?,?,?,?)
                """, (pid,week,team,opp,home_away,result,
                      targets,recs,rec_yds))
            total_logs += 1

        total_players += 1
        print(f"  Seeded {player_name} ({pos}) — {len(data['logs'])} games")

    conn.commit()
    conn.close()
    print(f"\nDone. {total_players} players, {total_logs} game logs seeded.")

if __name__ == "__main__":
    seed_expanded()
